const KEY='sls-reading-lab-v1';
const AUDIO_PROGRESS_KEY=KEY+':audio-progress';
function load(){
 try{
  const d=JSON.parse(localStorage.getItem(KEY)||'{}');
  const saved={profile:d.profile||{},favorites:Array.isArray(d.favorites)?d.favorites:[],records:Array.isArray(d.records)?d.records:[],custom:Array.isArray(d.custom)?d.custom:[],session:d.session||null,size:d.size||18};
  // A small separate checkpoint avoids rewriting all answer and result snapshots during playback.
  try{
   const progress=JSON.parse(localStorage.getItem(AUDIO_PROGRESS_KEY)||'null');
   if(saved.session&&progress?.sessionId===saved.session.id&&Number(progress.updatedAt)>Number(saved.session.audioUpdatedAt||0)){
    const allowed=new Set(saved.session.passageIds||[]),positions={...saved.session.audioPositions};
    for(const [id,value] of Object.entries(progress.positions||{}))if(allowed.has(id)&&Number.isFinite(value)&&value>=0)positions[id]=value;
    saved.session.audioPositions=positions;saved.session.audioUpdatedAt=Number(progress.updatedAt);
   }
  }catch{}
  return saved;
 }catch{return{profile:{},favorites:[],records:[],custom:[],session:null,size:18};}
}
