async function loadSiteJson(url,label){
 const controller=typeof AbortController==='function'?new AbortController():null;
 let timer;
 const request=(async()=>{const response=await fetch(url,controller?{signal:controller.signal}:{});if(!response.ok)throw Error(`${label}加载失败，请重新加载。`);return await response.json();})();
 const timeout=new Promise((_,reject)=>{timer=setTimeout(()=>{if(controller)controller.abort();reject(Error(`${label}加载超时，请检查网络后重试。`));},15000);});
 try{return await Promise.race([request,timeout]);}
 catch(error){const failure=Error(error?.name==='SyntaxError'?`${label}数据未能读取，请重新加载。`:error?.name==='TypeError'?`${label}无法连接，请检查网络后重试。`:error?.message||`${label}加载失败，请重新加载。`);failure.loadFailure=true;throw failure;}
 finally{clearTimeout(timer);}
}
